import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

final Uint8List _kBrandLogoBytes = base64Decode('');
final Uint8List _kBrandWordmarkBytes = base64Decode('');

/// Circular Flaming Siomai Emblem (shared artwork with Web System)
class KevsLogo extends StatelessWidget {
  final double size;

  const KevsLogo({super.key, this.size = 38.0});

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      width: size,
      height: size,
      child: Image.memory(
        _kBrandLogoBytes,
        width: size,
        height: size,
        fit: BoxFit.contain,
        filterQuality: FilterQuality.high,
        gaplessPlayback: true,
        semanticLabel: 'HOTSPOT Siomai Flaming Siomai Emblem',
      ),
    );
  }
}

/// HOTSPOT Siomai / STA. CRUZ FAMOUS SIOMAI Wordmark (shared artwork with Web System)
class KevsBrandWordmark extends StatelessWidget {
  final double height;

  const KevsBrandWordmark({super.key, this.height = 44.0});

  @override
  Widget build(BuildContext context) {
    final width = height * (177.0 / 46.0);
    return Semantics(
      label: 'HOTSPOT Siomai - STA. CRUZ FAMOUS SIOMAI',
      child: SizedBox(
        width: width,
        height: height,
        child: Image.memory(
          _kBrandWordmarkBytes,
          width: width,
          height: height,
          fit: BoxFit.contain,
          filterQuality: FilterQuality.high,
          gaplessPlayback: true,
        ),
      ),
    );
  }
}

/// Complete Brand Lockup: Flaming Siomai Emblem + HOTSPOT Siomai / STA. CRUZ FAMOUS SIOMAI
class KevsBrandLockup extends StatelessWidget {
  final double height;

  const KevsBrandLockup({super.key, this.height = 46.0});

  @override
  Widget build(BuildContext context) {
    final gap = (height * 0.13).clamp(5.0, 12.0);
    return Row(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.center,
      children: [
        KevsLogo(size: height),
        SizedBox(width: gap),
        Flexible(
          child: FittedBox(
            fit: BoxFit.scaleDown,
            alignment: Alignment.centerLeft,
            child: KevsBrandWordmark(height: height),
          ),
        ),
      ],
    );
  }
}